import { angleTo, direction, distance } from '../core/math';
import type { Projectile, Tank } from '../core/types';
import { actorTargetPoint, attachedTarget } from './actor-targets';
import { projectileImpact } from './effects';
import { tankHitLocation } from './hit-location';
import { projectileOutside } from './projectile-boundary';
import type { World } from './world';

const isHoming = (b: Projectile) => b.kind === 'orbital' || (b.kind === 'seeker' && b.enemy);
const attached = (world: World, tank?: Tank) =>
  tank !== undefined && attachedTarget(world, tank.uid) === tank;

function hitPoint(world: World, tank: Tank) {
  const center = actorTargetPoint(world, tank),
    hit = tankHitLocation(tank);
  return { x: center.x + hit.x - tank.x, y: center.y + hit.y - tank.y };
}

/** _-QM/_-JX latch _-Pk; a later turn never clears the <5px contact. */
function steer(world: World, b: Projectile) {
  const state = b.homing!;
  if (!state.target) {
    b.motion = direction(0, b.speed); // RotateTowardTarget returns0 without changing rotation.
    return;
  }
  const point = hitPoint(world, state.target);
  if (distance(b, point) < 5) state.close = true;
  b.angle = angleTo(b, point);
  b.motion = direction(b.angle, b.speed);
}

/** Base Setup calls the subclass steering method before the first MoveBullet. */
export function initializeHomingProjectile(world: World, b: Projectile) {
  if (!isHoming(b) || b.homing) return;
  b.homing = {
    home: attachedTarget(world, b.owner),
    target: attachedTarget(world, b.targetId),
    avatar: world.player,
    close: false,
  };
  steer(world, b);
}

function rotation(angle: number) {
  const value = angle % 360;
  return value > 180 ? value - 360 : value < -180 ? value + 360 : value;
}

/** _-JX._-Hz changes movement only in the distant, >=15-degree branch. */
function orbit(world: World, b: Projectile, home: Tank) {
  const center = actorTargetPoint(world, home);
  if (distance(b, center) > home.radius + 20) {
    let delta = angleTo(b, center) - b.angle;
    if (delta > 180) delta -= 360;
    else if (delta < -180) delta += 360;
    if (Math.abs(delta) < 15) return;
    b.angle = rotation(b.angle + delta / 20);
    b.motion = direction(b.angle, b.speed);
  } else {
    b.angle = rotation(b.angle + 5);
    const offset = direction(b.angle - 90, home.radius + 10);
    b.x = center.x + offset.x;
    b.y = center.y + offset.y;
    // This branch deliberately retains moveX/moveY from Setup or the previous pursuit.
  }
}

function targets(world: World, b: Projectile) {
  return b.enemy ? [b.homing!.avatar, ...world.allies] : [...world.field.enemies];
}

/** _-QM and _-JX use three projectile points, then current/backward tank points. */
function contact(world: World, b: Projectile) {
  const state = b.homing!;
  if (b.kind === 'seeker' && !attached(world, state.avatar)) {
    state.avatar = state.target = world.player;
    b.targetId = world.player.uid;
  }
  const motion = b.motion!;
  for (const shot of world.bullets)
    if (
      shot.enemy !== b.enemy &&
      [0, -0.5, 0.5].some((offset) =>
        world.hitProjectile(shot, b.x + motion.x * offset, b.y + motion.y * offset),
      )
    ) {
      projectileImpact(world, b);
      return true; // The intercepting shot is left intact, without its callback.
    }
  const candidates = b.kind === 'seeker' ? [state.avatar] : targets(world, b);
  for (const tank of candidates)
    if (
      state.close ||
      world.hitTest(tank, b.x, b.y) ||
      world.hitTest(tank, b.x - motion.x / 2, b.y - motion.y / 2)
    ) {
      projectileImpact(world, b);
      world.damage(tank, b.damage, b);
      return true;
    }
  return false;
}

export function tickHomingProjectile(world: World, b: Projectile) {
  initializeHomingProjectile(world, b);
  const state = b.homing!;
  if ((b.kind === 'orbital' && !attached(world, state.home)) || b.wipe) {
    projectileImpact(world, b);
    b.dead = true;
    return;
  }
  if (projectileOutside(world, b)) {
    world.addCombatEffect(b, 'impact');
    b.dead = true;
    return;
  }
  if (b.kind === 'seeker' || attached(world, state.target)) steer(world, b);
  else {
    orbit(world, b, state.home!);
    // Acquisition follows orbiting, and the selected tank is aimed at next frame.
    const target = targets(world, b).find(
      (tank) => distance(b, actorTargetPoint(world, tank)) - tank.radius < 100,
    );
    if (target) {
      state.target = target;
      b.targetId = target.uid;
    }
  }
  if (contact(world, b)) {
    b.dead = true;
    return;
  }
  b.x += b.motion!.x;
  b.y += b.motion!.y;
}
import { rotate } from '../core/math';
import { protectionScale } from '../core/protection-size';
import { legacyShieldFilm, shieldClipFrame } from '../core/shield-art';
import type { Tank, TankPart } from '../core/types';
import { partById } from '../data/catalog';
import { INFECTED_ART, PROTECTION_ART, shieldClipSymbol } from '../data/status-art';
import type { Bounds, SwfMatrix } from './asset-pack';
import { scriptBounds, type ScriptBoundsSource } from './projectile-bounds';
import type { SwfClip } from './swf-clip';

export interface TankBoundsClips {
  part(tank: Tank, part: TankPart): SwfClip | undefined;
  status(tank: Tank, index: number): SwfClip;
  infection(tank: Tank): SwfClip;
  forcefieldPart(tank: Tank, part: TankPart): SwfClip | undefined;
  forcefieldRadius(tank: Tank): number;
  protectionRadius(tank: Tank): number;
}

/** Script width includes invisible children and masks, without filter growth or raster padding. */
export function tankScriptBounds(tank: Tank, source: ScriptBoundsSource, clips: TankBoundsClips) {
  const boxes: Bounds[] = [];
  const add = (
    id: number,
    age: number,
    x = 0,
    y = 0,
    angle = 0,
    sx = 1,
    sy = sx,
    pose?: SwfClip,
  ) => {
    const position = rotate({ x, y }, tank.rotation),
      radians = ((tank.rotation + angle) * Math.PI) / 180,
      matrix: SwfMatrix = {
        a: Math.cos(radians) * sx,
        b: Math.sin(radians) * sx,
        c: -Math.sin(radians) * sy,
        d: Math.cos(radians) * sy,
        tx: position.x * 20,
        ty: position.y * 20,
      };
    const bounds = scriptBounds(source, id, age, matrix, undefined, [], 0, pose);
    if (bounds) boxes.push(bounds);
  };
  const addPart = (part: TankPart, pose: SwfClip | undefined, aimed: boolean) => {
    const id = partById(part.type)?.symbol;
    if (!id) return;
    add(
      id,
      pose?.age ?? 1,
      part.x,
      part.y,
      aimed
        ? (tank.guns.find((gun) => gun.part.key === part.key)?.angle ?? part.rotation)
        : part.rotation,
      part.scale,
      part.scale,
      pose,
    );
  };
  for (const part of tank.design.parts)
    if (!tank.removedParts.has(part.key) && tank.displayChildren.includes(`part:${part.key}`))
      addPart(part, clips.part(tank, part), true);
  if (tank.statusDecoration && tank.displayChildren.includes('status'))
    for (const [i, mark] of tank.statusDecoration.marks.entries()) {
      const pose = clips.status(tank, i);
      add(pose.id, pose.age, mark.x, mark.y, mark.angle, 1, 1, pose);
    }
  if (tank.status.infect > 0 && tank.displayChildren.includes('infection')) {
    const pose = clips.infection(tank);
    add(
      INFECTED_ART,
      pose.age,
      0,
      0,
      tank.infectionAngle,
      (tank.radius * 1.5) / 36,
      undefined,
      pose,
    );
  }
  const scaled = (id: number, frame: number, angle: number, diameter: number, uniform = false) => {
    const scale = protectionScale(scriptBounds(source, id, 1), diameter, uniform);
    add(id, frame, 0, 0, angle, scale.x, scale.y);
  };
  for (const clip of tank.shieldClips)
    if (tank.displayChildren.includes(clip.key))
      scaled(shieldClipSymbol(clip), shieldClipFrame(clip), clip.angle, clip.diameter);
  const film = legacyShieldFilm(tank),
    turret = tank.side !== 'player',
    diameter = turret ? tank.radius * 2 : (tank.shieldDiameter ?? clips.protectionRadius(tank) * 2);
  if (film)
    scaled(
      turret ? PROTECTION_ART.turretShield : PROTECTION_ART.shield,
      turret ? Math.min(25, tank.shieldAge + 1) : tank.shieldAge + 1,
      0,
      diameter,
    );
  if (film || tank.displayChildren.includes('shield-hit'))
    scaled(
      turret ? PROTECTION_ART.turretShieldHit : PROTECTION_ART.shieldHit,
      Math.min(16, tank.shieldHitAge + 1),
      tank.shieldHitAngle,
      tank.shieldHitDiameter ?? diameter,
    );
  if (tank.forcefieldAttached && tank.displayChildren.includes('forcefield')) {
    scaled(
      PROTECTION_ART.forcefield,
      tank.forcefieldFrame,
      tank.forcefieldAngle,
      clips.forcefieldRadius(tank) * 2.1,
      true,
    );
    // Flash includes the retained silhouette mask as well as the uncut field clip.
    for (const part of tank.design.parts) addPart(part, clips.forcefieldPart(tank, part), false);
  }
  if (!boxes.length) return undefined;
  const x = Math.min(...boxes.map((box) => box.x)),
    y = Math.min(...boxes.map((box) => box.y));
  return {
    x,
    y,
    width: Math.max(...boxes.map((box) => box.x + box.width)) - x,
    height: Math.max(...boxes.map((box) => box.y + box.height)) - y,
  };
}

